$(document).ready(function(){$("#daily-summary-form").submit(function(n){n.preventDefault();$.ajax({method:"POST",url:"/DailySummary/Index",data:$("#daily-summary-form").serialize()}).done(function(n){n&&($("#daily-summary-result").text(JSON.stringify(JSON.parse(n),null,2)),$(".daily-summary-field").removeClass("d-none"))})})});